212→  function buildChoiceQuestion(question) {
213→    var field = element("div", "field");
214→    var label = element("label", null, question.label);
215→    // The choices container is a div, so a <label for> cannot point at it. The
216→    // question text reaches assistive tech via role="group" + aria-labelledby.
217→    label.id = "label-" + question.key;
218→    var choices = element("div", "choice-options");
219→    choices.id = "answer-" + question.key;
220→    choices.role = "group";
221→    choices.setAttribute("aria-labelledby", "label-" + question.key);
222→    var elaborate = element("textarea", "answer-input elaborate");
223→    elaborate.rows = 2;
224→    elaborate.setAttribute("data-elaborate-for", question.key);
225→    elaborate.placeholder = "Tell us more (optional)";
226→    elaborate.setAttribute("aria-label", "Tell us more: " + question.label);
227→    elaborate.hidden = true;
228→
229→    ["Yes", "No"].forEach(function (choice) {
230→      var button = element("button", "choice-button", choice);
231→      button.type = "button";
232→      button.setAttribute("data-choice", choice);
233→      button.setAttribute("aria-pressed", "false");
234→      button.dataset.questionKey = question.key;
235→      button.addEventListener("click", function () {
236→        if (!button.classList.contains("selected")) {
237→          elaborate.value = "";
238→        }
239→        Array.prototype.forEach.call(choices.children, function (sibling) {
240→          sibling.classList.remove("selected");
241→          sibling.setAttribute("aria-pressed", "false");
242→        });
243→        button.classList.add("selected");
244→        button.setAttribute("aria-pressed", "true");
245→        show(elaborate);
246→      });
247→      choices.appendChild(button);
248→    });
249→
250→    field.appendChild(label);
251→    field.appendChild(choices);
252→    field.appendChild(elaborate);
253→    return field;
254→  }
